#!/usr/bin/env node
/**
 * Builds dist/lattice-default.css (the flattened, zero-config default) and dist/palettes/ (every palette, imports resolved).
 *
 * Lattice themes are Marp theme files: each declares `@theme <name>` and
 * pulls the engine in BY NAME via `@import 'lattice';`, which only Marp's
 * theme set resolves. That makes a bare theme file unusable as a
 * standalone stylesheet (a browser <link> cannot resolve the import).
 *
 * This generator resolves that import physically: it concatenates the
 * built engine (dist/lattice.css) with the default palette's token
 * blocks (everything AFTER the palette's `@import 'lattice';`), producing
 * a single self-contained file. Tokens come last, so they win by source
 * order — the same cascade contract every theme relies on. A consumer can
 * <link>/import this one file and get a themed deck with no theme
 * selection; to override, load a different palette's tokens after it.
 *
 * The default palette is cuoio (warm leather/cream). Change DEFAULT_THEME
 * to re-bless a different palette.
 *
 * THE PALETTES. The same step writes dist/palettes/<name>.css for every shipped
 * theme: that palette's token blocks with every `@import` resolved, published as
 * `@laticent/lattice/palette/<name>.css`. A bundler cannot import the Marp theme
 * file (Vite's CSS pipeline reads `@import 'lattice'` as a file path and stops with
 * ENOENT), so a non-Marp consumer imports the engine and then one palette:
 *
 *     import '@laticent/lattice/css';
 *     import '@laticent/lattice/palette/indaco.css';
 *
 * which is the composition the default bundle above flattens into one file. The
 * engine import is dropped (the consumer loads the engine once, whichever palette it
 * picks), a theme import (`@import 'cuoio'` in cuoio-dark) is replaced by that
 * theme's own resolved body, and comments are stripped, so no `@theme` header or
 * prose `@import` survives. Record: engineering/decisions/2026-09-23-portable-packages.md §10.
 *
 * Sibling: tools/build-css.js produces the engine this consumes; the
 * orchestrator (tools/build.js) runs this immediately after it.
 *
 * Usage:
 *   node tools/build-default-bundle.js          # write the bundle
 *   node tools/build-default-bundle.js --check   # CI/stale gate
 */

const fs = require('node:fs');
const path = require('node:path');
const { minifyCss } = require('./minify-css');

const ROOT = path.join(__dirname, '..');
const ENGINE = path.join(ROOT, 'dist', 'lattice.css');
const DEFAULT_THEME = 'cuoio';
const THEME = path.join(ROOT, 'themes', DEFAULT_THEME, `${DEFAULT_THEME}.css`);
const OUTPUT = path.join(ROOT, 'dist', 'lattice-default.css');
const MIN_OUTPUT = path.join(ROOT, 'dist', 'lattice-default-min.css');
const PALETTES_DIR = path.join(ROOT, 'dist', 'palettes');
const MIN_BANNER =
  '/* dist/lattice-default-min.css — GENERATED by tools/build-default-bundle.js (minified). Do not edit. SPDX-License-Identifier: AGPL-3.0-only. (c) 2025-2026 Laticent */';

const BANNER = [
  '/* dist/lattice-default.css — GENERATED by tools/build-default-bundle.js.',
  ' * Do not edit by hand.',
  ' * SPDX-License-Identifier: AGPL-3.0-only',
  ' * Copyright (c) 2025-2026 Laticent',
  ' *',
  ` * The flattened zero-config default: the engine (dist/lattice.css) plus`,
  ` * the ${DEFAULT_THEME} palette inlined, so this single file renders a themed`,
  ' * deck with no theme selection and can be dropped into a browser via one',
  ' * <link>. Tokens are appended last, so they win by source order; to',
  " * override, load another palette's token block after this file.",
  ' *',
  ' * Re-run `npm run default:build` after changing the engine or the',
  ' * default palette. CI gate: `npm run default:check`.',
  ' */',
  '',
].join('\n');

// Everything after the palette's `@import 'lattice';` — i.e. its token
// blocks, minus the @theme header comment and the name-based import.
function paletteTokens() {
  const css = fs.readFileSync(THEME, 'utf8');
  // Match the real at-rule (line-leading), not a mention inside the
  // theme's header comment (`@import 'lattice'` appears there as prose).
  const m = css.match(/^[ \t]*@import\s+['"]lattice['"]\s*;?/m);
  if (!m) {
    throw new Error(
      `themes/${DEFAULT_THEME}/${DEFAULT_THEME}.css has no \`@import 'lattice';\` — cannot locate the token block.`,
    );
  }
  return css.slice(m.index + m[0].length).replace(/^\s+/, '').replace(/\s+$/, '');
}

// A line-leading `@import '<name>';` — the at-rule, never prose (comments are gone by then).
const IMPORT_LINE_RE = /^[ \t]*@import\s+(['"])([^'"]+)\1\s*;?[ \t]*$/gm;

/** A theme's CSS with every import resolved: `lattice` dropped, another theme inlined. */
function resolvedPalette(name, chain = []) {
  if (chain.includes(name)) throw new Error(`palette import cycle: ${[...chain, name].join(' -> ')}`);
  const file = path.join(ROOT, 'themes', name, `${name}.css`);
  if (!fs.existsSync(file)) throw new Error(`${[...chain].pop() || name} imports '${name}', which is not a shipped theme (no themes/${name}/${name}.css)`);
  const { stripCssComments } = require('../lib/core/css-comments.mjs');
  const css = stripCssComments(fs.readFileSync(file, 'utf8'));
  return css
    .replace(IMPORT_LINE_RE, (_m, _q, dep) => (dep === 'lattice' ? '' : resolvedPalette(dep, [...chain, name])))
    .replace(/^[ \t]+$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/** Every shipped theme name: a `themes/<name>/<name>.css`, `_`-parked folders skipped. */
function paletteNames() {
  const dir = path.join(ROOT, 'themes');
  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((e) => e.isDirectory() && !e.name.startsWith('_') && fs.existsSync(path.join(dir, e.name, `${e.name}.css`)))
    .map((e) => e.name)
    .sort();
}

/** dist/palettes/<name>.css, as { name: text }. */
function palettes() {
  const out = {};
  for (const name of paletteNames()) {
    out[name] = `${[
      `/* @laticent/lattice/palette/${name}.css — GENERATED by tools/build-default-bundle.js from themes/${name}/${name}.css. Do not edit.`,
      ' * SPDX-License-Identifier: AGPL-3.0-only. (c) 2025-2026 Laticent',
      " * The palette's tokens with its imports resolved. Load it AFTER the engine (@laticent/lattice/css):",
      ` *   import '@laticent/lattice/css'; import '@laticent/lattice/palette/${name}.css';`,
      ' */',
    ].join('\n')}\n${resolvedPalette(name)}\n`;
  }
  return out;
}

function bundle() {
  const engine = fs.readFileSync(ENGINE, 'utf8').replace(/\s+$/, '');
  return [
    BANNER,
    engine,
    '',
    // The published name (`@laticent/lattice/themes/<name>.css`), kept as it was so the bundle's bytes do not move.
    `/* === default palette: themes/${DEFAULT_THEME}.css (engine import resolved) === */`,
    paletteTokens(),
    '',
  ].join('\n');
}

function main(argv) {
  if (!fs.existsSync(ENGINE)) {
    process.stderr.write('error: dist/lattice.css not found. Run `npm run css:build` first.\n');
    return 1;
  }
  const fresh = bundle();
  const freshMin = minifyCss(fresh, MIN_BANNER) + '\n';
  const freshPalettes = palettes();
  const read = (f) => (fs.existsSync(f) ? fs.readFileSync(f, 'utf8') : '');
  if (argv.includes('--check')) {
    const current = read(OUTPUT);
    const currentMin = read(MIN_OUTPUT);
    const stalePalettes = Object.entries(freshPalettes).filter(([n, text]) => read(path.join(PALETTES_DIR, `${n}.css`)) !== text).map(([n]) => n);
    const extra = fs.existsSync(PALETTES_DIR) ? fs.readdirSync(PALETTES_DIR).filter((f) => !freshPalettes[f.replace(/\.css$/, '')]) : [];
    if (stalePalettes.length || extra.length) {
      process.stderr.write(`error: dist/palettes/ is stale (${[...stalePalettes, ...extra].join(', ')}).\n       Run \`npm run default:build\` to regenerate.\n`);
      return 1;
    }
    if (current === fresh && currentMin === freshMin) {
      process.stdout.write(`lattice-default.css + lattice-default-min.css + dist/palettes/ (${Object.keys(freshPalettes).length}) are up to date.\n`);
      return 0;
    }
    process.stderr.write('error: lattice-default.css / lattice-default-min.css is stale relative to the engine/default palette.\n');
    process.stderr.write('       Run `npm run default:build` to regenerate.\n');
    return 1;
  }
  fs.mkdirSync(path.dirname(OUTPUT), { recursive: true });
  fs.writeFileSync(OUTPUT, fresh);
  fs.writeFileSync(MIN_OUTPUT, freshMin);
  // A palette whose theme was removed must not linger in the published package.
  fs.rmSync(PALETTES_DIR, { recursive: true, force: true });
  fs.mkdirSync(PALETTES_DIR, { recursive: true });
  for (const [name, text] of Object.entries(freshPalettes)) fs.writeFileSync(path.join(PALETTES_DIR, `${name}.css`), text);
  process.stdout.write(
    `wrote dist/lattice-default.css (${fresh.length.toLocaleString()} bytes) + ` +
      `dist/lattice-default-min.css (${freshMin.length.toLocaleString()} bytes, default: ${DEFAULT_THEME}) + ` +
      `dist/palettes/ (${Object.keys(freshPalettes).length} palettes, ${Object.values(freshPalettes).reduce((n, t) => n + t.length, 0).toLocaleString()} bytes)\n`,
  );
  return 0;
}

if (require.main === module) process.exit(main(process.argv.slice(2)));

module.exports = { bundle, palettes, resolvedPalette, main, OUTPUT, MIN_OUTPUT, PALETTES_DIR, DEFAULT_THEME };
